#include "ir.hpp"
#include <sstream>
namespace g2m {
IRModule lowerToIR(const Program&p){IRModule m;m.name=p.moduleName.empty()?"<anonymous>":p.moduleName;for(auto&f:p.functions){if(f.declarationOnly)continue;IRFunction x{f.name,{}};x.instructions.push_back({"function.begin","",f.returnType});for(auto&s:f.body){switch(s.kind){case Statement::Kind::Variable:x.instructions.push_back({"local",s.name,s.declaredType+" = "+s.value});break;case Statement::Kind::Expression:x.instructions.push_back({"eval","",s.value});break;case Statement::Kind::Return:x.instructions.push_back({"return","",s.value});break;case Statement::Kind::If:x.instructions.push_back({"if",s.condition,"nested body"});break;case Statement::Kind::While:x.instructions.push_back({"while",s.condition,"nested body"});break;case Statement::Kind::For:x.instructions.push_back({"for",s.name+"; "+s.condition+"; "+s.increment,"nested body"});break;case Statement::Kind::Block:x.instructions.push_back({"block","","nested body"});break;case Statement::Kind::Break:x.instructions.push_back({"break","",""});break;case Statement::Kind::Continue:x.instructions.push_back({"continue","",""});break;}}x.instructions.push_back({"function.end","",""});m.functions.push_back(std::move(x));}return m;}
std::string printIR(const IRModule&m){std::ostringstream o;o<<"module @"<<m.name<<" {\n";for(auto&f:m.functions){o<<"function @"<<f.name<<" {\n";for(auto&i:f.instructions){o<<"  ";if(!i.result.empty())o<<i.result<<" = ";o<<i.opcode;if(!i.operand.empty())o<<" "<<i.operand;o<<"\n";}o<<"}\n";}o<<"}\n";return o.str();}
}